<?php
require_once __DIR__.'/backend/authorization.php';require_once __DIR__.'/backend/db.php';require_once __DIR__.'/backend/csrf.php';requireSuperAdmin();
$message='';$type='success';
if($_SERVER['REQUEST_METHOD']==='POST'){
  verifyCsrf();$action=(string)($_POST['action']??'');
  if($action==='save'){
    $id=(int)($_POST['service_id']??0);$name=trim((string)($_POST['service_name']??''));$category=trim((string)($_POST['category']??'General'));$desc=trim((string)($_POST['description']??''));$price=(float)($_POST['price']??0);$duration=max(0,(int)($_POST['duration_minutes']??0));$status=in_array($_POST['status']??'active',['active','inactive'],true)?$_POST['status']:'active';
    if($name===''||$price<0){$message='Enter a valid service name and price.';$type='error';}
    else{try{if($id>0){$s=$conn->prepare('UPDATE services SET service_name=?,category=?,description=?,price=?,duration_minutes=?,status=? WHERE id=?');$s->bind_param('sssdisi',$name,$category,$desc,$price,$duration,$status,$id);$s->execute();audit($conn,'service_updated','service',$id);}else{$availability='available';$s=$conn->prepare('INSERT INTO services(service_name,category,description,price,duration_minutes,status,booking_availability,display_order) VALUES (?,?,?,?,?,?,?,999)');$s->bind_param('sssdiss',$name,$category,$desc,$price,$duration,$status,$availability);$s->execute();audit($conn,'service_created','service',(int)$conn->insert_id);} $message='Service saved.';}catch(Throwable $e){error_log($e->getMessage());$message='Service could not be saved. The name may already exist.';$type='error';}}
  }
}
$services=$conn->query('SELECT * FROM services ORDER BY category,display_order,service_name');
?>
