<section class="panel"><h2>Add Service</h2><form method="POST" class="form-grid four"><?=csrfInput()?><input type="hidden" name="action" value="save"><div class="field"><label>Category</label><input name="category" value="General" required></div><div class="field"><label>Name</label><input name="service_name" required></div><div class="field"><label>Price (PHP)</label><input name="price" type="number" min="0" step="0.01" required></div><div class="field"><label>Estimated Minutes</label><input name="duration_minutes" type="number" min="0" step="15" value="60"><small>Informational only; 0 = varies.</small></div><div class="field"><label>Catalog Status</label><select name="status"><option value="active">Active</option><option value="inactive">Inactive</option></select></div><div class="field span-3"><label>Description</label><input name="description"></div><div class="span-4"><button class="btn primary">Add Service</button></div></form></section>
<section class="panel"><h2>Current Services</h2><div class="table-scroll"><table><thead><tr><th>Category</th><th>Service</th><th>Description</th><th>Price</th><th>Est. Time</th><th>Catalog</th><th>Booking Availability</th><th>Update</th></tr></thead><tbody><?php while($s=$services->fetch_assoc()):$formId='service-form-'.(int)$s['id'];?><tr><td><input form="<?=$formId?>" name="category" value="<?=h($s['category'])?>"></td><td><input form="<?=$formId?>" name="service_name" value="<?=h($s['service_name'])?>"></td><td><input form="<?=$formId?>" name="description" value="<?=h($s['description'])?>"></td><td><input form="<?=$formId?>" name="price" type="number" step="0.01" value="<?=h($s['price'])?>"></td><td><input form="<?=$formId?>" name="duration_minutes" type="number" min="0" step="15" value="<?= (int)$s['duration_minutes']?>"></td><td><select form="<?=$formId?>" name="status"><option value="active" <?=$s['status']==='active'?'selected':''?>>Active</option><option value="inactive" <?=$s['status']==='inactive'?'selected':''?>>Inactive</option></select></td><td><span class="status <?= $s['booking_availability']==='available'?'approved':'neutral'?>"><?=h(ucfirst($s['booking_availability']))?></span><?php if($s['unavailable_reason']):?><br><small><?=h($s['unavailable_reason'])?></small><?php endif;?></td><td><form id="<?=$formId?>" method="POST"><?=csrfInput()?><input type="hidden" name="action" value="save"><input type="hidden" name="service_id" value="<?= (int)$s['id']?>"><button class="btn secondary tiny">Save</button></form></td></tr><?php endwhile;?></tbody></table></div></section></main></body></html>
